function source(id: string, title: string, author: string, organization: string, published: string, url: string, passage: string, access: HistorySource["access"], limitation: string): HistorySource {
  return { id: sid(id), title, author, organization, published, url, passage, access, limitation, verifiedAt: checked, documentKind: access === "abstract" ? "Résumé d’article original" : "Document scientifique ou institutionnel" };
}
