const sources = new Map(BOTANY_DIVERSITY_SOURCES.map(s => [s.id, s]));
const refs = (...keys: string[]) => keys.map(key => { const item = sources.get(sid(key)); if (!item) throw new Error(`Unknown botany source ${key}`); return item; });
const block = (text: string, evidence: HistoryBlock["evidence"], ...keys: string[]): HistoryBlock => ({ text, evidence, sourceIds: keys.map(sid) });
type Input = readonly [string, string, boolean, string];
const choices = (items: readonly Input[]): HistoryChoice[] => items.map(([id, text, correct, feedback]) => ({ id, text, correct, feedback }));
function step(id: string, prompt: string, options: readonly Input[], keys: string[], reasons?: readonly Input[]): HistoryStep {
  return { id, prompt, choices: choices(options), sourceIds: keys.map(sid), ...(reasons ? { reasonPrompt: "Quelle information justifie ce choix ?", reasons: choices(reasons) } : {}) };
}
const activity = (id: string, kind: HistoryActivity["kind"], title: string, evaluates: string, scenario: string, steps: readonly HistoryStep[], takeaway: string, fictional = false, documents?: HistoryActivity["documents"]): HistoryActivity => ({ id, kind, title, evaluates, scenario, steps, takeaway, fictional, ...(documents ? { documents } : {}) });

const taxonomyLessons: readonly HistoryLesson[] = [
  {
    id: "botany-taxonomy-1", title: "Classer une diversité sans la simplifier", question: "Sativa, indica et ruderalis sont-ils trois espèces établies une fois pour toutes ?", objective: "Distinguer un nom accepté dans un référentiel, un classement discuté et une étiquette commerciale.", minutes: 6,
    essential: [
      block("La taxonomie cherche à nommer et à classer les organismes selon des caractères et des hypothèses de parenté. Dans Plants of the World Online, Kew accepte Cannabis sativa L., au sein des Cannabaceae. Cela donne un référentiel commun pour désigner la plante. Le nom d’espèce, les subdivisions éventuelles et les synonymes doivent être lus dans le même système. Une liste de noms trouvés sur des étiquettes ne constitue pas, à elle seule, une liste d’espèces acceptées.", "observation", "kew"),
      block("L’ACIA explique que les classifications du genre Cannabis restent discutées : certains traitements retiennent une espèce très variable, d’autres plusieurs unités taxonomiques. Les populations domestiquées ont été déplacées et croisées, ce qui complique les frontières. Une différence de silhouette, d’usage ou de fréquence d’un variant génétique peut être réelle sans suffire à créer une espèce. Présenter sativa, indica et ruderalis comme trois cases biologiques certaines masque donc les critères et les débats. Il faut nommer l’auteur du classement et préciser ce qu’il permet réellement de comparer.", "interpretation", "cfia", "sawler"),
    ],
    example: block("Deux herbiers peuvent conserver des plantes comparables sous des noms historiques différents. Un botaniste vérifie les descriptions et les synonymes ; il ne conclut pas que chaque étiquette représente nécessairement une espèce distincte.", "interpretation", "kew"),
    deeper: [
      block("Un classement est une proposition scientifique organisée, pas un vote de popularité. On peut comparer morphologie, reproduction, distribution et données génétiques tout en restant en désaccord sur le rang à donner aux groupes. Les échanges entre populations et la domestication rendent l’exercice particulièrement délicat. La compatibilité reproductive est une information utile, mais ce n’est pas l’unique critère de toutes les conceptions de l’espèce. Une base taxonomique choisit un traitement cohérent sans prétendre rendre inutiles les recherches suivantes.", "interpretation", "cfia", "kew"),
      block("L’étude de Sawler et collègues observe des différences génétiques entre les groupes échantillonnés pour des usages différents, tout en montrant un fonds de variation partagé. Une séparation sur un graphique dépend des échantillons et des marqueurs analysés. Ce résultat ne transforme donc pas automatiquement chaque groupe commercial en espèce. La question utile devient : quelles plantes ont été comparées, avec quelle méthode, et à quelle conclusion les auteurs limitent-ils leurs observations ?", "experiment", "sawler"),
    ],
    visual: { kind: "comparison", title: "Trois niveaux à ne pas confondre", nodes: [{ label: "Référentiel", detail: "Kew : Cannabis sativa L., nom accepté" }, { label: "Recherche", detail: "Délimitation des groupes et histoire discutées" }, { label: "Commerce", detail: "Étiquettes appliquées à des produits ou lignées" }], caption: "Les trois colonnes ne répondent pas à la même question.", sourceIds: [sid("kew"), sid("cfia"), sid("schwabe")] },
    activity: activity("botany-taxonomy-activity-1", "documents", "Réparer le panneau du musée", "Choisir une formulation taxonomique vérifiable.", "Un panneau annonce : « Trois noms, donc trois espèces incontestées ». Relisez-le à partir de Kew et de l’ACIA.", [step("classification", "Quelle révision conserver ?", [["a", "Kew accepte Cannabis sativa ; d’autres traitements existent et leurs critères doivent être explicités.", true, "La phrase attribue le référentiel et conserve le débat scientifique."], ["b", "Chaque nom commercial constitue une nouvelle espèce.", false, "Nom de produit et délimitation d’espèce ne sont pas équivalents."], ["c", "Aucune différence entre populations n’existe puisque Kew retient une espèce.", false, "Une espèce peut comprendre une diversité importante."]], ["kew", "cfia"], [["a", "Les sources distinguent statut nomenclatural, variation biologique et classifications concurrentes.", true, "Cette justification précise le niveau auquel chaque affirmation s’applique."], ["b", "Le nombre de noms imprimés suffit à compter les espèces.", false, "Les synonymes et usages commerciaux empêchent cette déduction."]])], "Toujours préciser le référentiel avant de compter les espèces."),
    glossaryIds: ["botany-taxonomy", "botany-accession"], relatedLessonIds: ["botany-taxonomy-2", "botany-diversity-2"], nextQuestion: "Que peut réellement prédire une étiquette indica ou sativa ?",
  },
  {
    id: "botany-taxonomy-2", title: "Feuille, étiquette et profil : trois informations", question: "Une feuille large ou le mot sativa suffisent-ils à identifier une plante ?", objective: "Séparer caractère observé, nom commercial, profil mesuré et effet supposé.", minutes: 6,
    essential: [
      block("Une feuille se décrit : largeur des folioles, découpe, insertion et stade observé. Cette description appartient au phénotype. Le nom porté par un sachet ou une fiche appartient à un autre registre. Un profil chimique résulte encore d’une autre mesure, sur un échantillon et à une date. Associer directement une forme de feuille, un nom et un effet attendu court-circuite ces étapes. La comparaison devient fiable quand on conserve l’identité du prélèvement et la méthode employée.", "interpretation", "phenotype", "schwabe"),
      block("Les recherches sur des échantillons commerciaux constatent que les étiquettes indica, sativa ou hybride ne résument pas de façon constante toute leur structure génétique. Cela ne signifie pas que toutes les plantes sont identiques. Cela signifie que l’étiquette est une information insuffisante pour décrire chaque lot. De même, un nom géographique n’est ni un certificat de provenance ni une mesure de composition. Une carte Buddy peut raconter une sélection et ses sources ; elle ne remplace pas une analyse du matériel réel, encore moins une évaluation médicale ou la prédiction d’une expérience individuelle.", "experiment", "sawler", "schwabe"),
    ],
    example: block("Dans un exercice fictif, deux feuilles photographiées portent la même étiquette commerciale. La photographie permet de comparer leurs caractères visibles. Elle ne permet ni de vérifier que les plantes sont des clones, ni d’attribuer un dosage à leurs fleurs.", "fiction", "phenotype", "schwabe"),
    deeper: [
      block("Le mot type peut désigner une forme morphologique, un regroupement d’usage ou une catégorie chimique : il faut annoncer lequel. Ces descriptions peuvent être corrélées dans un échantillon sans être interchangeables. Pour tester une correspondance, on relie les observations et analyses au même matériel, puis on examine les exceptions et l’incertitude. Une moyenne sur un groupe n’est pas la valeur de chaque individu. Une différence génétique ne décrit pas, à elle seule, les conséquences d’un produit fini.", "interpretation", "sawler", "phenotype"),
      block("Le travail de Schwabe et McGlaughlin fournit une raison concrète de vérifier les noms : des échantillons portant le même nom n’ont pas toujours une identité génétique cohérente. La portée du constat reste celle de leur collecte et de leurs marqueurs. On ne peut ni accuser tous les fournisseurs d’erreur, ni déclarer tous les lots interchangeables. Conserver lot, provenance et date protège la comparaison ; les pourcentages commerciaux indica/sativa ne constituent pas un remplacement automatique de ces informations.", "experiment", "schwabe"),
    ],
    visual: { kind: "chain", title: "Quelle donnée répond à quelle question ?", nodes: [{ label: "Photographie", detail: "Un caractère visible, à un stade donné" }, { label: "Étiquette", detail: "Une identité annoncée à vérifier" }, { label: "Analyse", detail: "Une mesure reliée à un prélèvement" }, { label: "Conclusion", detail: "Limitée aux données réellement réunies" }], caption: "Aucune flèche ne transforme un nom en résultat de laboratoire.", sourceIds: [sid("phenotype"), sid("schwabe")] },
    activity: activity("botany-taxonomy-activity-2", "choice", "La légende trop sûre d’elle", "Reconnaître ce qu’une image permet d’établir.", "Une fiche fictive montre une feuille et annonce un effet garanti parce qu’elle est étiquetée sativa.", [step("photo", "Quelle légende est défendable ?", [["a", "Les folioles sont étroites sur cette photographie ; l’identité et la composition demandent d’autres données.", true, "La description reste au niveau de l’observation disponible."], ["b", "Cette feuille garantit une composition et le même effet pour tous.", false, "La photographie ne fournit ni analyse chimique ni évaluation individuelle."], ["c", "Le nom prouve que toutes les feuilles de la descendance seront identiques.", false, "Ni la filiation ni l’environnement ne sont établis par le nom."]], ["phenotype", "schwabe"], [["a", "Un caractère visible, une identité annoncée et une mesure sont trois informations distinctes.", true, "La justification repère précisément les données manquantes."], ["b", "Une silhouette constitue toujours un test ADN.", false, "L’apparence seule ne lit pas la séquence génétique."]])], "Décrire ce qui est observé avant de déduire ce qui ne l’est pas.", true),
    glossaryIds: ["botany-phenotype", "botany-genotype", "botany-pedigree"], relatedLessonIds: ["botany-taxonomy-1", "botany-genetics-1"], nextQuestion: "Une population locale et un clone conservent-ils la diversité de la même manière ?",
  },
];

const diversityLessons: readonly HistoryLesson[] = [
  {
    id: "botany-diversity-1", title: "Population, clone, cultivar : choisir le bon mot", question: "Qu’est-ce qui est conservé quand on conserve une variété ?", objective: "Distinguer population locale, plante férale, lignée, cultivar et clone sans les hiérarchiser.", minutes: 6,
    essential: [
      block("Une population réunit des individus : elle peut contenir plusieurs génotypes. Une population locale, souvent appelée landrace, s’inscrit dans une histoire de culture et de sélection sur un territoire. Le mot ne garantit ni une pureté absolue ni une absence d’échanges. Une plante férale descend de matériel cultivé et se maintient hors des cultures. Sa présence spontanée ne suffit donc pas à en faire un ancêtre sauvage intact. Pour la décrire, il faut conserver son lieu de collecte et ce que l’on sait de son histoire.", "interpretation", "cfia", "lynch2025"),
      block("Un clone désigne une descendance obtenue par multiplication végétative d’un individu ; il conserve en principe son patrimoine génétique, sous réserve de mutations et d’erreurs d’identité. Une lignée évoque une continuité de descendance, dont la méthode de maintien doit être précisée. Un cultivar est un ensemble cultivé reconnu par des caractères ; il n’est pas nécessairement constitué de clones identiques. Les descriptions officielles s’appuient sur du matériel de référence et des observations répétées. Aucun de ces mots ne permet, à lui seul, de classer une plante comme meilleure, plus ancienne, plus sûre ou plus efficace.", "interpretation", "geves", "geves-diversity"),
    ],
    example: block("Trois étiquettes fictives accompagnent une collection : « population locale, provenance connue », « plante échappée d’une ancienne culture » et « clone d’un individu identifié ». Elles décrivent trois histoires de matériel, pas trois degrés de qualité.", "fiction", "cfia", "geves"),
    deeper: [
      block("Le GEVES rappelle que l’homogénéité variétale est relative aux espèces et aux constructions génétiques. Une description stable peut tolérer une diversité interne ; inversement, plusieurs copies d’un clone n’élargissent pas beaucoup la diversité génétique représentée. Une collection conserve donc des individus mais aussi des métadonnées : origine déclarée, date, mode de maintien et lien entre l’échantillon actuel et l’échantillon initial. Sans cette continuité, une étiquette ancienne peut rester en place alors que le matériel a changé.", "interpretation", "geves", "geves-diversity"),
      block("Dans un pangénome, une accession est une entrée de collection ou un matériel identifié pour l’étude. Elle n’équivaut pas automatiquement à une variété entière, à toutes les plantes d’un territoire ou à une population ancestrale. Les chercheurs peuvent inclure des formes cultivées et férales pour comparer leur diversité. L’intérêt est précisément de documenter leurs différences, sans supposer qu’un nom traditionnel garantit un génome inchangé depuis des siècles. Les récits de provenance restent à confronter aux échantillons et aux analyses disponibles.", "experiment", "lynch2025"),
    ],
    visual: { kind: "comparison", title: "Quatre étiquettes, quatre questions", nodes: [{ label: "Population locale", detail: "Quelle histoire territoriale et quelle diversité interne ?" }, { label: "Férale", detail: "Quelle relation avec une culture passée ?" }, { label: "Clone", detail: "Quel individu initial et quelle traçabilité ?" }, { label: "Cultivar", detail: "Quels caractères décrits et maintenus ?" }], caption: "Ces catégories ne forment ni une échelle de pureté ni un classement de valeur.", sourceIds: [sid("cfia"), sid("geves"), sid("lynch2025")] },
    activity: activity("botany-diversity-activity-1", "matching", "Classer les fiches de collection", "Associer une description à un terme sans inventer d’ascendance.", "Une collection fictive reçoit trois lots accompagnés d’une description.", [step("feral", "Une plante issue d’anciennes cultures se maintient sans entretien. Quel terme convient ?", [["a", "Férale, si cette histoire est documentée.", true, "Le terme décrit une sortie du contexte cultivé."], ["b", "Ancêtre sauvage de toutes les variétés, obligatoirement.", false, "Une plante spontanée peut descendre de cultures récentes."], ["c", "Clone, parce qu’elle pousse seule.", false, "Le nombre de plantes visibles ne renseigne pas son mode de multiplication."]], ["cfia"], [["a", "L’histoire de provenance et de maintien compte davantage que la seule apparence spontanée.", true, "L’explication utilise la donnée qui distingue ici la plante férale."], ["b", "Toute plante sans étiquette commerciale est une landrace pure.", false, "L’absence d’étiquette ne démontre ni provenance ni pureté."]]), step("collection", "Quel dossier décrit le mieux un clone ?", [["a", "Même nom sur plusieurs sachets provenant de vendeurs différents.", false, "Un nom partagé ne prouve pas une multiplication à partir d’un même individu."], ["b", "Descendance végétative d’un individu identifié, avec un suivi des échantillons.", true, "Origine individuelle et mode de multiplication sont explicités."], ["c", "Toute une vallée contenant des plantes ressemblantes.", false, "Une ressemblance ne transforme pas une population en clone."]], ["geves", "schwabe"])], "Le vocabulaire décrit l’unité conservée et son histoire.", true),
    glossaryIds: ["botany-landrace", "botany-feral", "botany-clone", "botany-cultivar", "botany-accession"], relatedLessonIds: ["botany-diversity-2", "botany-genetics-1"], nextQuestion: "Combien d’échantillons faut-il pour représenter une diversité mondiale ?",
  },
  {
    id: "botany-diversity-2", title: "Le pangénome agrandit la carte", question: "Un grand catalogue de génomes contient-il déjà toute la diversité ?", objective: "Lire un résultat génomique avec ses unités, son échantillonnage et ses limites.", minutes: 6,
    essential: [
      block("Un génome de référence fournit un repère utile, mais il ne contient pas toutes les variations d’une espèce. Un pangénome combine plusieurs génomes pour décrire des séquences partagées et variables. Il peut représenter des différences de lettres, de segments, de présence de gènes ou d’organisation. Les méthodes et les matériels inclus déterminent ce qui devient visible. On ne lit donc pas un pangénome comme un arbre complet de toutes les variétés vendues dans le monde.", "interpretation", "lynch2025", "pike2026"),
      block("En 2025, Lynch et collègues réunissent 193 assemblages issus de 144 échantillons biologiques. En 2026, Pike et collègues présentent un graphe de 66 haplotypes, comprenant de nouveaux assemblages et des ressources déjà publiées. Ces nombres ne comptent pas la même chose : un individu diploïde peut fournir deux haplotypes. Les travaux soulignent une diversité encore incomplètement représentée, particulièrement dans certaines régions d’origine. Davantage de séquences n’efface pas automatiquement un biais de collecte. La bonne question porte sur les plantes incluses, leur provenance, la qualité des assemblages et celles qui manquent encore.", "experiment", "lynch2025", "pike2026"),
    ],
    example: block("Un graphique fictif compare « 144 échantillons » à « 66 haplotypes » comme s’il s’agissait de nombres de variétés. Il faut d’abord corriger les unités ; la taille de deux études ne se compare pas sur ces chiffres seuls.", "fiction", "lynch2025", "pike2026"),
    deeper: [
      block("Un haplotype correspond à une version liée d’un ensemble de positions génétiques. Séparer les versions d’un individu aide à éviter une reconstruction artificiellement mélangée. Un assemblage est la reconstruction informatique d’une séquence à partir de lectures ; sa continuité et sa précision sont évaluées, elles ne vont pas de soi. Le résumé de Pike et collègues signale certaines limites de qualité de ses nouveaux assemblages. Les chiffres sont ainsi accompagnés de critères nécessaires pour juger les usages possibles de la ressource.", "interpretation", "pike2026"),
      block("Ces études permettent de poser de meilleures questions sur la domestication, les échanges et la diversité structurale. Elles ne certifient pas automatiquement qu’un lot commercial descend de deux parents annoncés. Une analyse de proximité peut montrer des ressemblances ou des groupes ; établir un parentage exige une question et un dispositif adaptés, ainsi que des références identifiées. Il faut donc résister au raccourci « grand arbre génétique publié, tous les pedigrees désormais prouvés ». La carte scientifique reste liée à ses échantillons, ses méthodes et ses incertitudes.", "interpretation", "lynch2025", "schwabe"),
    ],
    visual: { kind: "comparison", title: "Lire les unités avant les nombres", nodes: [{ label: "2025 : 144", detail: "Échantillons biologiques étudiés" }, { label: "2025 : 193", detail: "Assemblages de génomes" }, { label: "2026 : 66", detail: "Haplotypes dans le graphe présenté" }, { label: "Encore ouvert", detail: "Diversité et territoires insuffisamment échantillonnés" }], caption: "Des unités distinctes, pas trois barres sur une échelle commune de nombre de variétés.", sourceIds: [sid("lynch2025"), sid("pike2026")] },
    activity: activity("botany-diversity-activity-2", "documents", "La comparaison impossible", "Repérer une confusion d’unités et une généralisation d’échantillon.", "Un panneau fictif annonce que 193 et 66 sont deux comptes de variétés uniques et exhaustifs.", [step("unit", "Quelle correction est nécessaire ?", [["a", "Préciser assemblages, individus et haplotypes avant toute comparaison.", true, "Les publications ne comptent pas les mêmes unités."], ["b", "Additionner 193 et 66 pour connaître toutes les variétés mondiales.", false, "Les unités diffèrent et certaines ressources sont réutilisées."], ["c", "Considérer chaque haplotype comme une espèce.", false, "Une version de séquence n’est pas une espèce biologique."]], ["lynch2025", "pike2026"], [["a", "Un individu peut fournir plusieurs séquences, et la collecte reste incomplète.", true, "La justification explique à la fois le comptage et la limite de représentativité."], ["b", "Le plus grand chiffre garantit l’absence de biais.", false, "La composition de l’échantillon compte autant que son effectif."]])], "Une ressource riche n’est ni un recensement exhaustif ni un certificat de pedigree.", true),
    glossaryIds: ["botany-pangenome", "botany-haplotype", "botany-accession", "botany-pedigree"], relatedLessonIds: ["botany-diversity-1", "botany-modern-lineages-1"], nextQuestion: "Que décrit exactement un génotype à une position de l’ADN ?",
  },
];

const geneticsLessons: readonly HistoryLesson[] = [
  {
    id: "botany-genetics-1", title: "Du génotype au caractère observé", question: "Deux plantes qui se ressemblent ont-elles forcément le même génotype ?", objective: "Lire les termes allèle, homozygote, hétérozygote et phénotype dans un modèle annoncé comme simplifié.", minutes: 6,
    essential: [
      block("Un allèle est une version d’une séquence à une position du génome. Pour un locus diploïde ordinaire, un individu porte deux copies : AA et aa représentent ici deux situations homozygotes, Aa une situation hétérozygote. Ces lettres sont des conventions de modèle, pas des mesures de qualité. Un individu peut être homozygote à une position et hétérozygote à une autre. Dire qu’une plante est hétérozygote sans préciser l’échelle étudiée laisse donc une partie de l’information dans l’ombre.", "observation", "allele", "genotype"),
      block("Le génotype décrit la composition génétique considérée ; le phénotype désigne des caractères observables. Leur relation dépend du caractère, d’autres régions du génome, du développement et de l’environnement. Deux plantes proches génétiquement peuvent présenter des différences visibles, et deux plantes ressemblantes ne sont pas nécessairement identiques génétiquement. Un caractère dit dominant dans un modèle ne signifie ni fréquent, ni supérieur, ni plus puissant. Il décrit une relation d’expression entre versions dans les conditions du modèle. Pour une plante réelle, il faut vérifier que ce modèle correspond bien au caractère étudié.", "interpretation", "phenotype", "genotype", "allele"),
    ],
    example: block("Modèle fictif d’un marqueur neutre : les dossiers AA et Aa portent la même couleur d’étiquette, selon une règle de dominance inventée pour l’exercice. La couleur ne permet donc pas de choisir entre les deux génotypes. Aucun caractère de cannabis n’est prédit par ce modèle.", "fiction", "allele", "genotype"),
    deeper: [
      block("Une expérience cherche à séparer ce qu’elle contrôle de ce qu’elle mesure. Si deux observations ne portent pas sur le même stade ou les mêmes conditions, une différence apparente ne démontre pas une différence génétique. Inversement, l’absence de différence visible ne démontre pas l’identité des séquences. La génétique ne se résume pas à remplacer chaque couleur ou chaque taille par une lettre. Beaucoup de caractères dépendent de plusieurs régions du génome et de leurs interactions avec le milieu.", "interpretation", "phenotype", "geves"),
      block("Les descriptions variétales utilisent des caractères définis et des comparaisons répétées, avec du matériel de référence. Elles rendent une observation plus reproductible sans prétendre lire tout l’ADN. Un génotypage apporte une autre information, limitée aux positions ou séquences qu’il examine. Les deux démarches peuvent se compléter. Dans une fiche de collection, la meilleure note conserve donc l’identité de l’échantillon, la méthode, le caractère et les conditions d’observation, plutôt que d’employer génotype et phénotype comme deux synonymes élégants de variété.", "interpretation", "geves", "genotype"),
    ],
    visual: { kind: "chain", title: "Observer sans sauter les étapes", nodes: [{ label: "Allèles", detail: "Versions à une position donnée" }, { label: "Génotype", detail: "Composition génétique considérée" }, { label: "Développement et milieu", detail: "Conditions qui participent à l’expression" }, { label: "Phénotype", detail: "Caractère observé selon une méthode" }], caption: "Schéma conceptuel : la relation n’est pas une formule universelle à un seul gène.", sourceIds: [sid("allele"), sid("genotype"), sid("phenotype")] },
    activity: activity("botany-genetics-activity-1", "diagram", "Deux dossiers, la même étiquette", "Éviter de déduire un génotype unique d’un phénotype.", "Dans le modèle fictif, AA et Aa donnent la même étiquette bleue ; aa donne une étiquette crème. Aucun caractère biologique réel n’est visé.", [step("genotype", "Un dossier porte l’étiquette bleue. Que peut-on en déduire ?", [["a", "Il peut correspondre à AA ou Aa dans ce modèle.", true, "La règle annoncée donne le même résultat visible pour deux génotypes."], ["b", "Il est nécessairement AA.", false, "Aa est aussi compatible avec l’étiquette bleue."], ["c", "Il possède une meilleure qualité biologique.", false, "La couleur fictive et la dominance n’évaluent aucune qualité."]], ["allele", "genotype"], [["a", "La correspondance entre génotype et résultat visible n’est pas ici univoque.", true, "La justification utilise exactement la règle de l’exercice."], ["b", "Un allèle dominant est toujours le plus fréquent et le meilleur.", false, "Dominance, fréquence et valeur sont trois notions différentes."]])], "Un modèle sert à raisonner à condition de garder visibles ses hypothèses.", true),
    glossaryIds: ["botany-allele", "botany-genotype", "botany-phenotype", "botany-heterozygosity"], relatedLessonIds: ["botany-genetics-2", "botany-taxonomy-2"], nextQuestion: "F1, F2 et autofloraison parlent-ils du même phénomène ?",
  },
  {
    id: "botany-genetics-2", title: "Générations et modes biologiques", question: "Comment distinguer générations, autofloraison, autofécondation et féminisation ?", objective: "Lire une descendance théorique et distinguer génération, floraison, fécondation et catégorie de semences.", minutes: 7,
    essential: [
      block("F1 désigne une première génération filiale issue de parents définis ; F2 désigne la génération issue de la reproduction de cette F1 selon le dispositif précisé. La ségrégation et la recombinaison peuvent faire apparaître de nouvelles combinaisons en F2. Le mot F1 ne promet pas à lui seul une uniformité parfaite : il faut connaître les parents et les caractères comparés. De même, hybride ne signifie pas nécessairement croisement entre espèces distinctes, et aucune génération ne garantit automatiquement une meilleure performance.", "interpretation", "f1f2", "geves"),
      block("L’introgression désigne l’incorporation durable de matériel génétique d’une population dans une autre à la suite d’hybridations et de transmissions. C’est une question d’histoire génétique, pas un simple synonyme de ressemblance. L’autofloraison concerne une réponse de floraison peu dépendante de la photopériode. L’autofécondation concerne l’origine des gamètes d’un même individu. La féminisation désigne, dans les catalogues, une production visant une descendance principalement femelle. Ces trois notions ne se déduisent pas les unes des autres : une étiquette auto ne dit ni comment une graine a été fécondée ni quelle identité génétique elle possède.", "interpretation", "introgression", "cfia", "cfia-seeds"),
    ],
    example: block("Une étiquette fictive indique « F1, autofloraison ». La première mention situe une génération annoncée ; la seconde décrit une réponse de floraison. Ni l’une ni l’autre ne démontre que toutes les plantes se fécondent elles-mêmes ou qu’elles sont des clones.", "fiction", "f1f2", "cfia"),
    deeper: [
      block("La présentation de JAX explique le cas précis de parents consanguins définis : leur F1 peut être uniforme à des positions où elle est pourtant hétérozygote, tandis que la F2 redistribue les combinaisons. Ce cas pédagogique ne doit pas être transformé en promesse applicable à tous les lots portant F1. Les générations ne sont pas des grades de qualité. Pour comprendre un arbre, on vérifie ce que chaque nœud représente : individu, population, lot ou simple nom, puis la signification exacte de chaque liaison.", "interpretation", "f1f2"),
      block("Une différence de vocabulaire peut même être cachée dans un nom propre : dans le témoignage de Jigga sur Cookies, F1 Durban contient un nom F1 expliqué par la course automobile. Ce mot ne prouve pas la génération expérimentale d’un lot actuel. Les dossiers variétaux attribuent donc les filiations au déclarant et séparent nomenclature biologique et marque commerciale. L’exercice consiste à lire des données et leurs limites ; il ne fournit ni calendrier de croisements, ni méthode pour produire des semences, ni sélection visant une composition particulière.", "interpretation", "cookies"),
    ],
    visual: { kind: "comparison", title: "Une étiquette, plusieurs axes", nodes: [{ label: "F1 / F2", detail: "Position dans une descendance définie" }, { label: "Autofloraison", detail: "Réponse de floraison à la photopériode" }, { label: "Autofécondation", detail: "Origine des gamètes" }, { label: "Féminisation", detail: "Catégorie visant l’expression femelle de la descendance" }], caption: "Ces axes sont distincts ; aucun n’est un résultat d’analyse de composition.", sourceIds: [sid("f1f2"), sid("cfia"), sid("cfia-seeds")] },
    activity: activity("botany-genetics-activity-2", "matching", "Remettre les mots dans leur colonne", "Distinguer des phénomènes que les catalogues rapprochent parfois.", "Le conservateur reçoit des étiquettes isolées, sans procédure de production.", [step("auto", "Que renseigne directement autofloraison ?", [["a", "La réponse de floraison, peu dépendante de la durée du jour.", true, "Le terme porte sur la floraison."], ["b", "Une autofécondation obligatoire.", false, "L’origine des gamètes est une autre question."], ["c", "L’identité génétique parfaite de toutes les plantes.", false, "Une réponse de floraison ne définit pas un clone."]], ["cfia"], [["a", "Floraison, fécondation et identité génétique sont des axes distincts.", true, "La justification évite de transférer une propriété à un autre axe."], ["b", "Le préfixe auto rend tous ces mots équivalents.", false, "Un préfixe commun ne donne pas la même définition."]]), step("f2", "Dans une descendance théorique, que peut-il arriver en F2 ?", [["a", "Des combinaisons d’allèles se redistribuent ; l’uniformité de la F1 ne suffit pas à les prédire individuellement.", true, "La génération suivante peut présenter une ségrégation."], ["b", "Chaque descendant reproduit nécessairement tout le génome d’un parent F1.", false, "Ce serait confondre reproduction sexuée et copie clonale."], ["c", "Tous les caractères deviennent automatiquement supérieurs.", false, "Le rang de génération n’est pas une évaluation de performance."]], ["f1f2"])], "Identifier le phénomène avant d’interpréter l’étiquette."),
    glossaryIds: ["botany-f1", "botany-f2", "botany-introgression", "botany-autoflowering", "botany-selfing", "botany-feminisation"], relatedLessonIds: ["botany-genetics-1", "botany-modern-lineages-2"], nextQuestion: "Comment représenter une parenté annoncée sans lui donner une certitude excessive ?",
  },
];

const modernLessons: readonly HistoryLesson[] = [
  {
    id: "botany-modern-lineages-1", title: "Le pedigree est un dossier de preuves", question: "Un arbre de noms est-il déjà une preuve de parenté ?", objective: "Attribuer chaque filiation, conserver sa version et distinguer récit, document et test.", minutes: 6,
    essential: [
      block("Un pedigree représente une descendance annoncée ou établie à partir d’informations identifiées. Pour le lire, il faut savoir ce que désignent les noms : un clone particulier, une population, une sélection d’un obtenteur ou une famille commerciale. Une flèche sans source peut donner une impression trompeuse de précision. Une filiation déclarée par l’obtenteur est une information utile, mais sa publication ne transforme pas automatiquement la relation biologique en résultat indépendant de laboratoire.", "interpretation", "schwabe", "cannatonic"),
      block("Cannatonic offre un exemple vérifiable : en novembre 2015, Resin Seeds remplace sa précédente attribution MK-Ultra × G13 par Reina Madre × NYCD. La rectification est un document primaire sur ce que l’obtenteur affirme ; elle ne contient pas de test indépendant de parentage. Les dossiers doivent conserver cette date et la limite. De même, deux versions White Widow peuvent annoncer des parents différents sans que l’une soit silencieusement utilisée comme définition de toutes les autres. Nom, obtenteur, version et provenance forment ensemble l’unité de comparaison.", "observation", "cannatonic", "widow"),
    ],
    example: block("La fiche Buddy HH2026-003 renvoie à la correction publiée pour Cannatonic. Elle permet de retrouver le document et son auteur, même sans posséder la carte. Elle ne certifie pas l’identité d’un échantillon extérieur portant ce nom.", "interpretation", "cannatonic"),
    deeper: [
      block("Une pièce datée peut établir qu’un nom et une déclaration existaient à une période donnée. Un témoignage rétrospectif établit d’abord le récit de son auteur, avec les limites de sa mémoire et de son intérêt commercial. Une analyse génétique apporte d’autres données, mais sa capacité à conclure dépend des références, marqueurs et hypothèses. Une proximité entre deux échantillons ne suffit pas à décider lequel serait parent de l’autre. Il faut éviter de convertir automatiquement une ressemblance en flèche généalogique orientée.", "interpretation", "schwabe", "sawler"),
      block("La mention inconnu est donc une information positive : elle marque ce qui manque au dossier. Elle peut concerner un parent non publié, une date précise, la continuité du matériel ou l’identité d’un clone. La recherche peut ensuite viser ce manque plutôt que le remplir d’un récit plausible. Les arbres proposés ici conservent l’attribution et les réserves de chaque liaison. Aucun lien n’est qualifié de génétiquement établi pour rendre le dessin plus complet ou plus séduisant.", "interpretation", "cannatonic", "schwabe"),
    ],
    visual: { kind: "evidence", title: "Ce que chaque pièce établit", nodes: [{ label: "Catalogue daté", detail: "Une déclaration publiée à une date" }, { label: "Témoignage", detail: "Le récit attribué à son auteur" }, { label: "Analyse", detail: "Un résultat lié à des échantillons identifiés" }, { label: "Inconnu", detail: "Une donnée à rechercher, pas à inventer" }], caption: "La certitude du document et la certitude de la relation biologique sont distinctes.", sourceIds: [sid("cannatonic"), sid("schwabe")] },
    activity: activity("botany-modern-lineages-activity-1", "documents", "Mettre à jour une filiation", "Intégrer une rectification avec une attribution et une limite.", "Vous comparez l’ancienne parenté annoncée de Cannatonic à la rectification de Resin Seeds du 10 novembre 2015.", [step("correction", "Quelle note faut-il afficher ?", [["a", "Resin Seeds déclare depuis 2015 Reina Madre × NYCD ; vérification indépendante non fournie dans cette page.", true, "La note conserve le contenu, la date, l’auteur et la limite."], ["b", "Les deux parentés sont simultanément prouvées par ADN.", false, "La page est une rectification déclarative, pas deux analyses ADN."], ["c", "Tout document corrigé doit être supprimé sans garder sa date.", false, "L’historique de la correction explique précisément pourquoi les récits diffèrent."]], ["cannatonic"], [["a", "Le document primaire prouve la correction publiée, sans fournir tous les moyens de vérifier biologiquement les parents.", true, "On distingue ce qui est documenté de ce qui est encore à confirmer."], ["b", "Une déclaration commerciale est automatiquement un certificat de parentage.", false, "Les deux types de preuve ne sont pas équivalents."]])], "Garder auteur, date et limite rend l’arbre révisable.", false, [{ title: "Rectification Resin Seeds, 2015", text: "L’obtenteur remplace l’ancienne attribution MK-Ultra × G13 par Reina Madre × NYCD.", status: "Paraphrase du texte primaire consulté ; aucun test de parentage présenté", sourceIds: [sid("cannatonic")] }]),
    glossaryIds: ["botany-pedigree", "botany-accession", "botany-cultivar"], relatedLessonIds: ["botany-modern-lineages-2", "botany-diversity-2"], buddyCodes: ["HH2026-003", "HH2026-022"], nextQuestion: "Comment comparer deux dossiers appartenant à une même famille commerciale ?",
  },
  {
    id: "botany-modern-lineages-2", title: "Dix familles, plusieurs histoires", question: "Que faut-il comparer derrière Haze, Kush, Cookies ou CBD ?", objective: "Parcourir les dix dossiers et expliquer un écart de versions sans transformer une hypothèse en certitude.", minutes: 7,
    essential: [
      block("Haze, Skunk, Northern Lights, Kush, Diesel, Blueberry, White Widow, Cookies et Gelato sont des noms ou familles issus de récits de sélection et de circulation. Hybrides CBD regroupe ici des exemples liés à une composition recherchée, pas une espèce ni un ancêtre commun unique. Les dix dossiers utilisent la même grille : origine revendiquée, période attestée par les pièces, auteur déclaré, parents annoncés, variantes et inconnues. Cette structure rend les récits comparables sans prétendre leur donner tous le même niveau de preuve.", "interpretation", "schwabe", "cannatonic"),
      block("Le comparateur doit conserver les écarts. La White Widow de Trikoma annonce Widow Bilbo × Widow BCN ; cette version ne devient pas la définition de tout matériel appelé White Widow. Un parent seulement nommé lignée CBD reste non identifié. Un nombre dans le nom d’un clone ne devient pas une date, un pourcentage ou une génération. Les Buddies donnent des portes d’entrée vers les fiches déjà documentées du Quartier, mais les dossiers restent consultables sans possession. Leur rôle est d’aider à lire des sources et à reconnaître les informations manquantes.", "interpretation", "widow", "cookies"),
    ],
    example: block("Dans le récit de Jigga, F1 Durban est un nom parental. Le lecteur qui le transforme automatiquement en première génération F1 ajoute une information que le témoignage n’établit pas. C’est précisément le genre d’erreur que le dossier doit empêcher.", "observation", "cookies"),
    deeper: [
      block("Comparer ne consiste pas à élire le récit le plus détaillé. Un dossier court avec des inconnues claires peut être plus fiable qu’un arbre immense sans sources. Pour chaque flèche, on demande qui l’affirme, pour quel matériel, à quelle période et avec quelle preuve. Un entretien de l’obtenteur peut être une source primaire sur son travail tout en restant intéressé et rétrospectif. Un catalogue conservé peut stabiliser une date de présence, sans établir le jour exact d’un croisement antérieur.", "interpretation", "cannatonic", "cookies"),
      block("Les études de noms commerciaux invitent à garder la traçabilité, pas à abandonner toute histoire variétale. On peut documenter des pratiques, des acteurs et des déclarations tout en refusant une certitude génétique excessive. Les dossiers n’ajoutent donc ni pourcentage chimique garanti, ni effet médical, ni conseil de production. Leur conclusion utile est une question précise à poursuivre : manque-t-il un document daté, une version du catalogue, une identification du parent ou une analyse réalisée sur du matériel de référence ?", "interpretation", "schwabe", "sawler"),
    ],
    visual: { kind: "comparison", title: "La même grille pour chaque dossier", nodes: [{ label: "Identité", detail: "Nom + obtenteur + version" }, { label: "Temps et lieu", detail: "Revendication séparée du document daté" }, { label: "Filiation", detail: "Liaisons attribuées, sources visibles" }, { label: "Limites", detail: "Parents inconnus, variantes et absence de test" }], caption: "Les dix familles sont des dossiers de lecture, pas dix branches taxonomiques certaines.", sourceIds: [sid("schwabe"), sid("cannatonic"), sid("widow")] },
    activity: activity("botany-modern-lineages-activity-2", "dossier", "Deux noms identiques, deux dossiers", "Comparer des versions sans fusionner leurs pedigrees.", "Un catalogue indique une White Widow issue de deux sélections Widow ; un autre dossier conserve une autre déclaration d’origine. Aucun test comparatif n’est fourni.", [step("versions", "Comment présenter ces informations ?", [["a", "Créer une seule filiation universelle avec tous les parents réunis.", false, "Cela fabriquerait une généalogie qu’aucun document ne déclare."], ["b", "Garder deux versions attribuées et signaler que leur identité génétique n’est pas vérifiée ici.", true, "Les écarts restent lisibles, sans choisir arbitrairement une vérité unique."], ["c", "Déclarer les deux dossiers faux parce qu’ils diffèrent.", false, "Des sélections distinctes peuvent porter un même nom ; l’écart demande une enquête."]], ["widow", "schwabe"], [["a", "Le nom seul ne suffit pas à identifier le matériel et les déclarations concernent des versions distinctes.", true, "La justification relie la provenance au bon niveau de comparaison."], ["b", "L’arbre le plus long est nécessairement le plus fiable.", false, "La quantité de nœuds ne remplace pas la qualité des preuves."]])], "Préserver les différences de versions évite d’inventer un ancêtre commun."),
    glossaryIds: ["botany-pedigree", "botany-cultivar", "botany-f1"], relatedLessonIds: ["botany-modern-lineages-1", "botany-genetics-2"], buddyCodes: ["HH2026-022", "HH2026-026", "HH2026-003"], nextQuestion: "Quel dossier pourriez-vous enrichir avec une pièce précise plutôt qu’avec une supposition ?",
  },
];

